namespace SemsApi.DTO
{
    /// <summary>
    /// Request payload for creating or updating a Form.
    /// FormId, CreatedBy and CreatedAt are intentionally omitted -
    /// they are generated by the database / taken from the authenticated user.
    /// </summary>
    public class FormRequestDto
    {
        /// <summary>0 = all students, 1 = Preschool to Grade 3, 2 = Grade 4 to 6, 3 = JHS to SHS.</summary>
        public int? ProgramId { get; set; }

        /// <summary>The evaluation type the form uses. Determines its categories and questions.</summary>
        public int? EvaluationTypeId { get; set; }

        public string? Title { get; set; }
        public string? Description { get; set; }

        /// <summary>
        /// Optional. 1 = active, 0 = inactive/draft. On create, null means 1. On update, null leaves the current value unchanged.
        /// </summary>
        public int? IsActive { get; set; }
    }
}